using System;
using System.IO;
using Avalonia.Controls;
using Avalonia.Interactivity;
using Avalonia.Media.Imaging;

namespace Backoffice;

public partial class MainWindow : Window
{

    Business business;
    Product special;

    public MainWindow()
    {
        InitializeComponent();

        special = new Product(
            "PROD-0000",
            "Baklava",
            "",
            1.30f
        );

        business = new Business(
            "COM-0000",
            "Kose's Business",
            "Logo",
            special
        );

        AfficherBusiness();
    }


    private void AfficherBusiness()
    {
        BusinessNameText.Text = business.Name;
        BusinessIdText.Text = $"Nom commerce : {business.Id}";

        ProductNameText.Text = business.Special.Name;
        ProductPriceText.Text = $"Prix : {business.Special.Price:0.00} CHF";

        // Base64 -> image
        var bytes = Convert.FromBase64String(business.Special.Picture);
        ProductImage.Source = new Bitmap(new MemoryStream(bytes));
    }

    private void OnClick_ExportButton(object? sender, RoutedEventArgs e)
    {
        special.ExportJson();
        Console.WriteLine("Export button clicked!");
    }
}